fn require_initialized_for(
        &self,
        method_family: &str,
    ) -> Result<SessionHandle, JSONRPCErrorError> {
        if !self.initialize_requested.load(Ordering::SeqCst) {
            return Err(invalid_request(format!(
                "client must call initialize before using {method_family} methods"
            )));
        }
        let session = self.require_session_attached()?;
        if !self.initialized.load(Ordering::SeqCst) {
            return Err(invalid_request(format!(
                "client must send initialized before using {method_family} methods"
            )));
        }
        Ok(session)
    }

attachment_guard.excerpt:
fn require_session_attached(&self) -> Result<SessionHandle, JSONRPCErrorError> {
        let Some(session) = self.session() else {
            return Err(invalid_request(
                "client must call initialize before using methods".to_string(),
            ));
        };
        if session.is_session_attached() {
            return Ok(session);
        }

        Err(invalid_request(
            "session has been resumed by another connection".to_string(),
        ))
    }

initialize_transition.excerpt:
async fn initialize(
        &self,
        params: InitializeParams,
    ) -> Result<InitializeResponse, JSONRPCErrorError> {
        if self.initialize_requested.swap(true, Ordering::SeqCst) {
            return Err(invalid_request(
                "initialize may only be sent once per connection".to_string(),
            ));
        }

        let session = match self
            .session_registry
            .attach(
                params.resume_session_id.clone(),
                self.notifications.clone(),
                self.runtime_paths.clone(),
            )
            .await
        {
            Ok(session) => session,
            Err(error) => {
                self.initialize_requested.store(false, Ordering::SeqCst);
                return Err(error);
            }
        };
        let session_id = session.session_id().to_string();
        tracing::debug!(
            session_id,
            connection_id = %session.connection_id(),
            "exec-server session attached"
        );
        *self
            .session
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(session);
        Ok(InitializeResponse {
            session_id,
            environment_info: Some(local_environment_info()),
        })
    }

initialized_transition.excerpt:
fn initialized(&self) -> Result<(), String> {
        if !self.initialize_requested.load(Ordering::SeqCst) {
            return Err("received `initialized` notification before `initialize`".into());
        }
        self.require_session_attached()
            .map_err(|error| error.message)?;
        self.initialized.store(true, Ordering::SeqCst);
        Ok(())
    }

notification_dispatch.excerpt:
async fn handle_notification(
        &mut self,
        notification: JSONRPCNotification,
    ) -> RequestTaskResult {
        let is_initialized = notification.method == INITIALIZED_METHOD;
        let Some(route) = self.router.notification_route(notification.method.as_str()) else {
            warn!(
                "closing exec-server connection after unexpected notification: {}",
                notification.method
            );
            return RequestTaskResult::ConnectionClosed;
        };
        let result = tokio::select! {
            result = route(Arc::clone(&self.handler), notification) => result,
            _ = self.disconnected_rx.changed() => {
                debug!("exec-server transport disconnected while handling notification");
                return RequestTaskResult::ConnectionClosed;
            }
        };
        if let Err(error) = result {
            warn!("closing exec-server connection after protocol error: {error}");
            return RequestTaskResult::ConnectionClosed;
        }
        if is_initialized {
            self.initialized = true;
        }

        RequestTaskResult::Completed
    }

request_dispatch.excerpt:
async fn dispatch_request(
        &mut self,
        request: JSONRPCRequest,
        request_span: tracing::Span,
        queued_at: Instant,
    ) -> RequestTaskResult {
        let started_at = Instant::now();
        let Some((method, route)) = self.router.request_route(request.method.as_str()) else {
            let method = "unknown";
            self.telemetry
                .request_queue_completed(method, queued_at.elapsed());
            request_span.record("otel.name", method);
            request_span.record(
                "rpc.dispatch_offset_ns",
                i64::try_from(queued_at.elapsed().as_nanos()).unwrap_or(i64::MAX),
            );
            if self
                .outgoing_tx
                .send(RpcServerOutboundMessage::Error {
                    request_id: request.id,
                    error: method_not_found(format!(
                        "exec-server stub does not implement `{}` yet",
                        request.method
                    )),
                })
                .await
                .is_err()
            {
                request_span.record("result", "disconnected");
                self.telemetry.request_completed(
                    method,
                    "disconnected",
                    started_at.elapsed(),
                    queued_at.elapsed(),
                );
                return RequestTaskResult::ConnectionClosed;
            }
            request_span.record(
                "rpc.response_enqueue_offset_ns",
                i64::try_from(queued_at.elapsed().as_nanos()).unwrap_or(i64::MAX),
            );
            request_span.record("result", "error");
            self.telemetry.request_completed(
                method,
                "error",
                started_at.elapsed(),
                queued_at.elapsed(),
            );
            return RequestTaskResult::Completed;
        };

        request_span.record("otel.name", method);
        let route_setup_started_at = Instant::now();
        let route = route(Arc::clone(&self.handler), request);
        let route_setup_duration = route_setup_started_at.elapsed();
        let outgoing_tx = self.outgoing_tx.clone();
        let mut disconnected_rx = self.disconnected_rx.clone();
        let telemetry = self.telemetry.clone();
        let task = async move {
            request_span.record(
                "rpc.dispatch_offset_ns",
                i64::try_from(queued_at.elapsed().as_nanos()).unwrap_or(i64::MAX),
            );
            telemetry.request_queue_completed(
                method,
                queued_at.elapsed().saturating_sub(route_setup_duration),
            );
            let message = tokio::select! {
                message = route.instrument(request_span.clone()) => message,
                _ = disconnected_rx.changed() => {
                    request_span.record("result", "disconnected");
                    telemetry.request_completed(
                        method,
                        "disconnected",
                        started_at.elapsed(),
                        queued_at.elapsed(),
                    );
                    return RequestTaskResult::ConnectionClosed;
                }
            };
            let result = request_result(&message);
            let response_sent = match message {
                Some(message) => {
                    let response_sent = tokio::select! {
                        result = outgoing_tx.send(message) => result.is_ok(),
                        _ = disconnected_rx.changed() => false,
                    };
                    if response_sent {
                        request_span.record(
                            "rpc.response_enqueue_offset_ns",
                            i64::try_from(queued_at.elapsed().as_nanos()).unwrap_or(i64::MAX),
                        );
                    }
                    response_sent
                }
                None => true,
            };
            if !response_sent {
                request_span.record("result", "disconnected");
                telemetry.request_completed(
                    method,
                    "disconnected",
                    started_at.elapsed(),
                    queued_at.elapsed(),
                );
                return RequestTaskResult::ConnectionClosed;
            }
            request_span.record("result", result);
            telemetry.request_completed(method, result, started_at.elapsed(), queued_at.elapsed());
            RequestTaskResult::Completed
        };

        let Some(RequestLanes { ordinary, control }) = &self.lanes else {
            // Keep requests ordered when concurrent dispatch is not enabled.
            return task.await;
        };
        // Finish the handshake before concurrent requests can observe session state.
        if method == INITIALIZE_METHOD || !self.initialized {
            return task.await;
        }

        // Reserve capacity for health checks and cleanup while ordinary requests are blocked.
        let admission = if matches!(
            method,
            ENVIRONMENT_INFO_METHOD
                | ENVIRONMENT_STATUS_METHOD
                | EXEC_SIGNAL_METHOD
                | EXEC_TERMINATE_METHOD
                | FS_CLOSE_METHOD
        ) {
            Arc::clone(control)
        } else {
            Arc::clone(ordinary)
        };

        // TODO(anp) bound queued request bytes without blocking later responses or cleanup.
        self.tasks.spawn(async move {
            let Ok(_permit) = admission.acquire_owned().await else {
                return RequestTaskResult::ConnectionClosed;
            };
            task.await
        });
        RequestTaskResult::Completed
    }

