reverse_request_timeout.excerpt:
async fn call_with_timeout<P, T>(
        &self,
        method: &str,
        params: &P,
        call_timeout: Duration,
    ) -> Result<T, RpcCallError>
    where
        P: Serialize,
        T: DeserializeOwned,
    {
        let _call_slot = self.inner.call_slots.try_acquire().map_err(|_| {
            RpcCallError::PendingRequestLimitExceeded {
                limit: MAX_IN_FLIGHT_SERVER_CALLS,
            }
        })?;
        let params = serde_json::to_value(params).map_err(RpcCallError::Json)?;
        let request_id =
            RequestId::Integer(self.inner.next_request_id.fetch_add(1, Ordering::SeqCst));
        let (response_tx, response_rx) = oneshot::channel();
        {
            let mut pending = self
                .inner
                .pending
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if self.inner.closed.is_cancelled() {
                return Err(RpcCallError::Closed);
            }
            pending.insert(request_id.clone(), response_tx);
        }
        let _pending = PendingServerRequestGuard {
            inner: Arc::clone(&self.inner),
            request_id: request_id.clone(),
        };
        let trace = codex_otel::current_span_w3c_trace_context().map(|mut trace| {
            if trace
                .tracestate
                .as_ref()
                .is_some_and(|tracestate| tracestate.len() > MAX_SERVER_REQUEST_TRACESTATE_LEN)
            {
                trace.tracestate = None;
            }
            trace
        });
        let request = RpcServerOutboundMessage::Request(JSONRPCRequest {
            id: request_id,
            method: method.to_string(),
            params: Some(params),
            trace,
        });

        let response = timeout(call_timeout, async {
            tokio::select! {
                biased;
                _ = self.inner.closed.cancelled() => return Err(RpcCallError::Closed),
                result = self.inner.outgoing_tx.send(request) => {
                    result.map_err(|_| RpcCallError::Closed)?;
                }
            }
            response_rx.await.map_err(|_| RpcCallError::Closed)?
        })
        .await
        .map_err(|_| RpcCallError::TimedOut {
            method: method.to_string(),
            timeout: call_timeout,
        })??;
        serde_json::from_value(response).map_err(RpcCallError::Json)
    }

outbound_notification_limiter.excerpt:
fn client_inbound_message_exceeded_limit(
    message: Result<&JSONRPCMessage, &serde_json::Error>,
    encoded_len: usize,
    max_request_len: usize,
) -> Option<usize> {
    let max_len = match message {
        Ok(JSONRPCMessage::Notification(notification))
            if matches!(
                notification.method.as_str(),
                EXEC_OUTPUT_DELTA_METHOD
                    | EXEC_EXITED_METHOD
                    | EXEC_CLOSED_METHOD
                    | HTTP_REQUEST_BODY_DELTA_METHOD
            ) =>
        {
            MAX_CLIENT_INBOUND_NOTIFICATION_LEN
        }
        Ok(JSONRPCMessage::Request(_)) | Ok(JSONRPCMessage::Notification(_)) | Err(_) => {
            max_request_len
        }
        Ok(JSONRPCMessage::Response(_)) | Ok(JSONRPCMessage::Error(_)) => return None,
    };
    (encoded_len > max_len).then_some(max_len)
}

